for(const role of fixture.stableIndex.cancellationRoles)test('actual cached row group cancellation at bounded publication stage '+role,async()=>{const value=tables(),abort=new AbortController();let armed=false,reached=false;const operation=sqliteOperation({signal:abort.signal,onProgress:event=>{if(armed&&event.phase==='reconstructSnapshot'){reached=true;abort.abort();}}}),index=await rowIndex().create(value,operation);expect(await index.grouped('entity',BigInt(fixture.stableIndex.originalParent),2)).toEqual(fixture.stableIndex.originalPositions.map(position=>flat(value)[position]));const admitted=operation.ownedBytes;expect(admitted).toBeGreaterThan(0);armed=true;const parent=role==='cached-present'?fixture.stableIndex.originalParent:fixture.stableIndex.unknownParent;await expect(index.grouped('entity',BigInt(parent),2)).rejects.toMatchObject({kind:'canceled'});expect(reached).toBe(true);expect(operation.ownedBytes).toBe(admitted);});
